START TRANSACTION;
DROP TABLE IF EXISTS `legacy_erp_users`;
DROP TABLE IF EXISTS `apprenants_brut`;
DROP TABLE IF EXISTS `formateurs_brut`;
DROP TABLE IF EXISTS `staff_pedagogiques_brut`;
DROP TABLE IF EXISTS `admins_brut`;
CREATE TABLE admins_brut (
    id INTEGER PRIMARY KEY,
    nom VARCHAR(100),
    prenom VARCHAR(100),
    email VARCHAR(255),
    date_creation DATETIME,
    is_active BOOLEAN,
    role VARCHAR(50),
    niveau_acces VARCHAR(50),
    date_promotion DATE
);
CREATE TABLE apprenants_brut (
    id INTEGER PRIMARY KEY,
    nom VARCHAR(100),
    prenom VARCHAR(100),
    email VARCHAR(255),
    date_creation DATETIME,
    is_active BOOLEAN,
    role VARCHAR(50),
    date_naissance DATE,
    niveau_etude VARCHAR(50),
    telephone VARCHAR(50),
    date_inscription_plateforme DATETIME,
    certification_obtenue VARCHAR(100)
);
CREATE TABLE formateurs_brut (
    id INTEGER PRIMARY KEY,
    nom VARCHAR(100),
    prenom VARCHAR(100),
    email VARCHAR(255),
    date_creation DATETIME,
    is_active BOOLEAN,
    role VARCHAR(50),
    specialite VARCHAR(100),
    date_embauche DATE,
    taux_horaire FLOAT,
    bio TEXT
);
CREATE TABLE legacy_erp_users (
    id INTEGER PRIMARY KEY,
    nom VARCHAR(100),
    prenom VARCHAR(100),
    email VARCHAR(255),
    date_creation DATETIME,
    is_active BOOLEAN,
    role VARCHAR(50),
    date_naissance DATE,
    niveau_etude VARCHAR(50),
    telephone VARCHAR(50),
    date_inscription_plateforme DATETIME,
    certification_obtenue VARCHAR(100),
    specialite VARCHAR(100),
    date_embauche DATE,
    taux_horaire FLOAT,
