CREATE TABLE staff_pedagogiques_brut (
    id INTEGER PRIMARY KEY,
    nom VARCHAR(100),
    prenom VARCHAR(100),
    email VARCHAR(255),
    date_creation DATETIME,
    is_active BOOLEAN,
    role VARCHAR(50),
    poste VARCHAR(100),
    date_prise_fonction DATE,
    responsabilites TEXT
);
COMMIT;
